// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface ISwapRouter02 {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata params)
        external
        payable
        returns (uint256 amountOut);
}

contract DCA {
    address public immutable owner;
    ISwapRouter02 public immutable router;
    address public immutable tokenIn;
    address public immutable tokenOut;
    uint24 public immutable fee;

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor(address _router, address _tokenIn, address _tokenOut, uint24 _fee) {
        owner = msg.sender;
        router = ISwapRouter02(_router);
        tokenIn = _tokenIn;
        tokenOut = _tokenOut;
        fee = _fee;
    }

    function deposit(uint256 amount) external {
        require(IERC20(tokenIn).transferFrom(msg.sender, address(this), amount), "transferFrom failed");
    }

    function buy(uint256 amountIn, uint256 minOut) external onlyOwner {
        require(IERC20(tokenIn).approve(address(router), amountIn), "approve failed");

        router.exactInputSingle(
            ISwapRouter02.ExactInputSingleParams({
                tokenIn: tokenIn,
                tokenOut: tokenOut,
                fee: fee,
                recipient: address(this),
                amountIn: amountIn,
                amountOutMinimum: minOut,
                sqrtPriceLimitX96: 0
            })
        );
    }

    function withdraw(address token, uint256 amount) external onlyOwner {
        require(IERC20(token).transfer(owner, amount), "transfer failed");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

contract Vault {
    IERC20 public immutable asset;
    uint256 public totalShares;
    uint256 public totalAssets;
    mapping(address => uint256) public shares;

    constructor(address _asset) { asset = IERC20(_asset); }

    // Internal accounting: share price is derived from totalAssets, a value
    // only deposit/withdraw can move. Tokens transferred directly to the
    // vault never enter the exchange rate, so donation-based inflation is a
    // pure gift to existing holders and the attack cannot strand a depositor
    // at zero shares.
    function deposit(uint256 amount) external returns (uint256 s) {
        require(amount > 0, "zero deposit");
        s = totalShares == 0 ? amount : (amount * totalShares) / totalAssets;
        require(s > 0, "zero shares");
        shares[msg.sender] += s;
        totalShares += s;
        totalAssets += amount;
        require(asset.transferFrom(msg.sender, address(this), amount), "transfer failed");
    }

    function withdraw(uint256 s) external returns (uint256 amount) {
        require(s > 0, "zero shares");
        amount = (s * totalAssets) / totalShares;
        shares[msg.sender] -= s;
        totalShares -= s;
        totalAssets -= amount;
        require(asset.transfer(msg.sender, amount), "transfer failed");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

/// @title Vault
/// @notice Yield-bearing share vault. Yield arrives as plain transfers of the
///         underlying asset and accrues pro-rata to existing shareholders.
/// @dev    Uses virtual-share/virtual-asset offset accounting (one virtual
///         share backed by one virtual asset) so that:
///         - share price starts at 1 and only rises with donated yield,
///         - both conversions round down, so a deposit->redeem round trip can
///           never mint value out of thin air,
///         - a first-depositor donation/inflation attack costs the attacker at
///           least as much as any victim could lose, and zero-share deposits
///           revert so a victim's funds can never be absorbed for nothing.
contract Vault {
    IERC20 public immutable asset;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;

    constructor(address _asset) {
        require(_asset != address(0), "zero asset");
        asset = IERC20(_asset);
    }

    /// @notice Total underlying held by the vault, including plain-transfer yield.
    function totalAssets() public view returns (uint256) {
        return asset.balanceOf(address(this));
    }

    /// @notice Deposit `assets` of underlying, minting shares rounded down.
    function deposit(uint256 assets) external returns (uint256 shares) {
        require(assets > 0, "zero assets");

        // Price shares off the balance BEFORE this deposit's tokens arrive.
        // Virtual offset: +1 share, +1 asset. Round down (in the vault's favor).
        shares = (assets * (totalSupply + 1)) / (totalAssets() + 1);
        require(shares > 0, "zero shares");

        _safeTransferFrom(msg.sender, address(this), assets);

        totalSupply += shares;
        balanceOf[msg.sender] += shares;
    }

    /// @notice Burn `shares`, returning underlying rounded down.
    function redeem(uint256 shares) external returns (uint256 assets) {
        require(shares > 0, "zero shares");
        require(balanceOf[msg.sender] >= shares, "insufficient shares");

        // Same virtual offset, rounding down: the sum of all pro-rata payouts
        // can never exceed the vault's balance, in any redemption order.
        assets = (shares * (totalAssets() + 1)) / (totalSupply + 1);

        balanceOf[msg.sender] -= shares;
        totalSupply -= shares;

        _safeTransfer(msg.sender, assets);
    }

    // ---- internal safe-transfer helpers (tolerate no-return-value tokens) ----

    function _safeTransfer(address to, uint256 amount) internal {
        (bool ok, bytes memory data) =
            address(asset).call(abi.encodeWithSelector(IERC20.transfer.selector, to, amount));
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "transfer failed");
    }

    function _safeTransferFrom(address from, address to, uint256 amount) internal {
        (bool ok, bytes memory data) =
            address(asset).call(abi.encodeWithSelector(IERC20.transferFrom.selector, from, to, amount));
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "transferFrom failed");
    }
}
